def bad_character_heuristic(self):
    """
    Finds all occurrences of the pattern in the text.
    :return: A list of all positions of the pattern in the text, list.
    >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
    >>> boyerMooreSearch.bad_character_heuristic()
    [0, 3]

    """
    results = []

    if self.patLen == 0 or self.textLen < self.patLen:
        return results

    # Build bad character shift table - map each character to its last occurrence index in pattern
    bad_char_table = {}
    for i in range(self.patLen):
        char = self.pattern[i]
        bad_char_table[char] = i

    pos = 0
    while pos <= self.textLen - self.patLen:
        mismatch = self.mismatch_in_text(pos)

        if mismatch == -1:
            results.append(pos)
            pos += self.patLen
        else:
            mismatch_char = self.text[pos + mismatch]

            if mismatch_char not in bad_char_table:
                shift = self.patLen
            elif bad_char_table[mismatch_char] < mismatch:
                shift = mismatch - bad_char_table[mismatch_char]
            else:
                shift = 1

            pos += shift

    return results

